import itertools
import numpy as np

def calculate_S(numbers):
    min_max_sum = float('inf')
    for p in itertools.permutations(numbers):
        current_max_sum = 0
        current_sum = 0
        for x in p:
            current_sum += x
            current_max_sum = max(current_max_sum, abs(current_sum))
        min_max_sum = min(min_max_sum, current_max_sum)
    return min_max_sum

def calculate_G_max(numbers):
    def get_max_G(current_remaining, current_sum, current_max):
        if not current_remaining:
            return current_max

        min_abs = float('inf')
        for x in current_remaining:
            min_abs = min(min_abs, abs(current_sum + x))

        best_vals = [x for x in current_remaining if abs(current_sum + x) == min_abs]

        max_G = 0
        for x in best_vals:
            rem = list(current_remaining)
            rem.remove(x)
            max_G = max(max_G, get_max_G(rem, current_sum + x, max(current_max, abs(current_sum + x))))
        return max_G

    min_abs_start = float('inf')
    for x in numbers:
        min_abs_start = min(min_abs_start, abs(x))

    best_vals_start = [x for x in numbers if abs(x) == min_abs_start]

    max_G = 0
    for x in best_vals_start:
        rem = list(numbers)
        rem.remove(x)
        max_G = max(max_G, get_max_G(rem, x, max(0, abs(x))))
    return max_G

def test_m(m, iterations=1000):
    min_ratio = 1.0
    for _ in range(iterations):
        # Try integers and some floats
        mode = np.random.rand()
        if mode < 0.5:
            numbers = [np.random.randint(-10, 11, m).tolist()]
        else:
            numbers = [np.random.uniform(-10, 10, m).tolist()]

        if sum(abs(x) for x in numbers) == 0:
            continue

        S = calculate_S(numbers)
        G = calculate_G_max(numbers)
        if G > 0:
            min_ratio = min(min_ratio, S / G)
    return min_ratio

for m in range(3, 9):
    print(f"m={m}: {test_m(m)}")

